import anyio
from starlette.websockets import WebSocket,WebSocketDisconnect,WebSocketState
scope={'type':'websocket','path':'/','headers':[]}
async def receive():
    return {'type':'websocket.disconnect','code':1001,'reason':'done'}
async def send(message):
    pass
async def exercise():
    websocket=WebSocket(scope,receive,send)
    try:
        await websocket.receive_json(mode='invalid')
    except Exception as exc:
        assert type(exc) is RuntimeError
    else:
        raise AssertionError('invalid mode did not raise')
    try:
        await websocket.send({'type':'websocket.send'})
    except Exception as exc:
        assert type(exc) is RuntimeError
    else:
        raise AssertionError('invalid transition did not raise')
    websocket.application_state=WebSocketState.CONNECTED
    websocket.client_state=WebSocketState.CONNECTED
    try:
        await websocket.receive_text()
    except Exception as exc:
        assert type(exc) is WebSocketDisconnect
        assert exc.code == 1001 and exc.reason == 'done'
    else:
        raise AssertionError('peer disconnect did not raise')
anyio.run(exercise)
